import base64

print("[+] Menyiapkan file bot auto-farming...")

files = {
    'run_auto_joe.py': "",
    'temp_mail_helper.py': "",
    'joe_source.py': ""
}

for filename, b64_data in files.items():
    print(f"[*] Menulis {filename}...")
    with open(filename, 'wb') as f:
        f.write(base64.b64decode(b64_data))

print("[✓] Semua file berhasil dibuat! Silakan jalankan: python run_auto_joe.py")
